import java.time.Duration;
import java.util.UUID;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Component;

@Component
class RefreshTokenService {

    private static final String KEY_PREFIX = "auth:refresh:";
    private static final Duration REFRESH_TTL = Duration.ofDays(7);

    private final StringRedisTemplate redisTemplate;

    RefreshTokenService(StringRedisTemplate redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    String issue(Long userId) {
        String refreshToken = UUID.randomUUID().toString();
        redisTemplate.opsForValue().set(KEY_PREFIX + refreshToken, userId.toString(), REFRESH_TTL);
        return refreshToken;
    }

    Long rotate(String oldRefreshToken) {
        // TODO: doc userId tu key KEY_PREFIX + oldRefreshToken; neu khong ton
        // tai (null), coi la refresh token bi tai su dung/khong hop le - nem
        // mot exception nghiep vu, KHONG issue token moi.
        // Neu ton tai: XOA ngay ban ghi cu (redisTemplate.delete(...)) truoc
        // khi tra ve userId cho tang goi tu issue(...) mot cap access/refresh
        // token moi - thu tu xoa-truoc-issue-sau dam bao tinh single-use.
        return null;
    }
}

