import jakarta.persistence.*;
import org.hibernate.annotations.NotFound;
import org.hibernate.annotations.NotFoundAction;
import org.springframework.data.jpa.repository.EntityGraph;
import org.springframework.data.jpa.repository.Query;
import java.util.List;

interface ProductRepository extends org.springframework.data.repository.Repository<ProductEntity, Long> {

    // Cach 1: JOIN FETCH tuong minh trong JPQL - nap Category cung mot cau
    // truy van duy nhat, thay vi de proxy lazy tu phat sinh N truy van rieng le.
    @Query("select p from ProductEntity p join fetch p.category")
    List<ProductEntity> findAllWithCategoryJoinFetch();

    // Cach 2: tuong duong Cach 1 bang @EntityGraph, khong can viet JPQL thu
    // cong. Dat ten khac findAll() vi Repository<T, ID> la marker interface
    // khong khai bao san method nao - day KHONG phai override, chi la mot
    // query method doc lap do ban tu khai bao, giong findAllWithCategoryJoinFetch().
    @EntityGraph(attributePaths = "category")
    List<ProductEntity> findAllWithCategoryGraph();
}

@Entity
class ProductEntity {

    @Id
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "category_id")
    @NotFound(action = NotFoundAction.IGNORE)
    private CategoryEntity category;
}

